/*
 * Accent presets, switched at runtime with data-accent on <html> (no attribute = neutral).
 * The attribute also works on any element to give one section its own accent.
 * Generated by tooling/scripts/gen-theme.mjs from the theme-<name> registry items; import after the theme.
 */

html[data-accent="neutral"],
[data-accent="neutral"] {
  --primary: oklch(10% 0 0);
  --primary-hover: oklch(22% 0 0);
  --primary-active: oklch(30% 0 0);
  --primary-foreground: oklch(100% 0 0);
  --primary-subtle: oklch(10% 0 0 / 0.04);
  --primary-subtle-hover: oklch(10% 0 0 / 0.08);
  --primary-border: oklch(10% 0 0 / 0.14);
  --primary-text: oklch(10% 0 0);
  --ring: oklch(66% 0 0);
  --selection: oklch(10% 0 0 / 0.14);
}

html[data-accent="neutral"].dark,
.dark [data-accent="neutral"] {
  --primary: oklch(98.5% 0 0);
  --primary-hover: oklch(91% 0 0);
  --primary-active: oklch(84% 0 0);
